    body.theme-dark .sidebar{background:#0c1b27}body.theme-dark .search,body.theme-dark .chip,body.theme-dark .tool-btn,body.theme-dark .route-panel,body.theme-dark .route-panel select,body.theme-dark .detail,body.theme-dark .action,body.theme-dark .map-status,body.theme-dark .interaction-button,body.theme-dark .comment-filter button,body.theme-dark .comment-form textarea,body.theme-dark .comment-reply-form textarea{border-color:#365564;background:#102735;color:var(--ink)}body.theme-dark .result:hover,body.theme-dark .result.active,body.theme-dark .route-panel,body.theme-dark .comment-item{background:#142e3d}body.theme-dark .result p,body.theme-dark .detail-summary,body.theme-dark .detail-more{color:var(--muted)}body.theme-dark .label{background:#173c45;color:#8de0d4}body.theme-dark .detail-close{background:#1b3948;color:var(--ink)}body.theme-dark .map-status{box-shadow:0 8px 22px #0008}body.theme-dark .comment-replies{border-color:#3d7b78}body.theme-dark .comment-item.is-pinned{border-color:#4faaa0;background:#183941}body.theme-dark .leaflet-tile{filter:brightness(.62) saturate(.72) hue-rotate(145deg)}body.theme-dark .leaflet-control-zoom a{background:#102735;color:#edf5f8;border-color:#365564}body.theme-dark .marker-tag{border-color:#365564;background:#102735;color:#d7f5ef}
